  std::vector<std::unique_ptr<DPMSourceBatchT>> SOURCES{};
  std::unique_ptr<DPMQueryBindingT> QUERY{};
  std::vector<std::unique_ptr<DPMCompletenessIndexT>> INDEXES{};
