  auto _SOURCES = _o->SOURCES.size() ? _fbb.CreateVector<::flatbuffers::Offset<DPMSourceBatch>> (_o->SOURCES.size(), [](size_t i, _VectorArgs *__va) { return CreateDPMSourceBatch(*__va->__fbb, __va->__o->SOURCES[i].get(), __va->__rehasher); }, &_va ) : 0;
  auto _QUERY = _o->QUERY ? CreateDPMQueryBinding(_fbb, _o->QUERY.get(), _rehasher) : 0;
  auto _INDEXES = _o->INDEXES.size() ? _fbb.CreateVector<::flatbuffers::Offset<DPMCompletenessIndex>> (_o->INDEXES.size(), [](size_t i, _VectorArgs *__va) { return CreateDPMCompletenessIndex(*__va->__fbb, __va->__o->INDEXES[i].get(), __va->__rehasher); }, &_va ) : 0;
  auto _ENCRYPTION = _o->ENCRYPTION ? CreateDPMEncryptionBinding(_fbb, _o->ENCRYPTION.get(), _rehasher) : 0;
